import re

with open('doc/molecule.md', 'r') as f:
    content = f.read()

# Find all molecule IDs
carcinogenic = set()
non_carcinogenic = set()

# Pattern to capture molecule ID with surrounding context
pattern = r'(?:designated|specimen|compound|analysis of|subject of|molecular structure|analyte|The assessment of|Next, the molecule|moving forward|Similarly, the analyte|The specimen identified as|The molecule registered as|Our investigation of|The analysis continued with|Following this|The molecular framework|The assessment of|Following the analysis|The evaluation of|The analysis of|The screening of|Following this|Our analysis of|The molecule identified as|Specimen|Molecule|As the computational screening progressed|The next compound in the queue|Finally)(?:\s+)?(TR\d{3})'

for match in re.finditer(pattern, content):
    mol_id = match.group(1)
    # Get context around the match
    start = max(0, match.start() - 300)
    end = min(len(content), match.end() + 300)
    context = content[start:end].lower()

    # Check if it's carcinogenic
    if 'carcinogenic' in context or 'positive' in context:
        # Check if it was corrected to carcinogenic from non-carcinogenic
        if 'non-carcinogenic' in context:
            if 'corrected' in context or 'revision' in context or 'update' in context or 'reconcile' in context:
                carcinogenic.add(mol_id)
            elif 'incorrectly' in context or 'erroneously' in context or 'mistakenly' in context or 'wrong' in context:
                carcinogenic.add(mol_id)
            elif 'initially' in context and 'positive' in context:
                carcinogenic.add(mol_id)
            elif 'also' in context and 'carcinogenic' in context:
                carcinogenic.add(mol_id)
            else:
                non_carcinogenic.add(mol_id)
        else:
            carcinogenic.add(mol_id)
    elif 'non-carcinogenic' in context:
        non_carcinogenic.add(mol_id)

print(f'Carcinogenic ({len(carcinogenic)}): {sorted(carcinogenic)}')
print(f'Non-carcinogenic ({len(non_carcinogenic)}): {sorted(non_carcinogenic)}')
print(f'Total unique: {len(carcinogenic) + len(non_carcinogenic)}')

